pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: caller address (could be admin or not) and a newOwner address
    function testFuzz_property(address caller, address newOwner) public {
        // keep addresses wide but avoid zero address for clarity (still admissible)
        // do not exclude admin: we want to ensure property holds for ALL inputs on reference
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));

        // admin is the deployer (this contract created c in setUp via new C())
        // So the admin inside C is address(this) from setUp context, i.e., this test contract.
        // We need to simulate a call from `caller` to c.setOwner(newOwner).

        bool ok;
        // perform the call as the fuzzed caller
        vm.prank(caller);
        try c.setOwner(newOwner) returns (bool success) {
            ok = success;
        } catch {
            ok = false;
        }

        // The general rule (reference): only admin (the deployer, i.e., this contract) can call setOwner
        // Therefore: for ANY caller != admin, a call to setOwner should NOT change owner; instead it should revert
        // or otherwise not succeed. We observe this by checking that if caller != address(this) then the call did not succeed
        // and owner remains equal to the original owner (which was set in constructor to the deployer of C).

        // Read the owner getter
        address currentOwner = c.owner();
        address constructorOwner = address(this); // when c was deployed in setUp, msg.sender was this test contract

        // The single assertion: if the caller is not the admin (this contract), then setOwner must not have succeeded
        // and owner must still equal the constructor-set owner. This holds for the reference for ALL inputs,
        // but the mutant (which removes onlyAdmin) will allow non-admin callers to change owner for some inputs,
        // causing this assertion to fail for those inputs.
        if (caller != address(this)) {
            assertTrue(currentOwner == constructorOwner);
        } else {
            // If caller is admin, call should succeed and owner should equal newOwner
            assertTrue(currentOwner == newOwner);
        }
    }
}

